const data = $input.first().json;
const errorMsg = data.execution?.error?.message || 'Error desconocido';
const nodoFallido = data.execution?.error?.node?.name || data.execution?.lastNodeExecuted || 'Desconocido';
const workflowName = data.execution?.workflowData?.name || 'Flow 2';
const executionId = data.execution?.id || '';
const executionUrl = data.execution?.url || '';
return [{ json: { errorMsg, nodoFallido, workflowName, executionId, executionUrl } }];

const err = $('Extraer Info Error').first().json;
const config = $('Leer Configuracion').first().json;
const twilioAuth = 'Basic ' + Buffer.from(config.twilio_account_sid + ':' + config.twilio_auth_token).toString('base64');
const twilioUrl = 'https://api.twilio.com/2010-04-01/Accounts/' + config.twilio_account_sid + '/Messages.json';
const adminTel = String(config.telefono_admin || '').replace(/\D/g, '');
const mensaje = '⚠️ ERROR crítico en RecepIA

Flow: ' + err.workflowName + '
Nodo: ' + err.nodoFallido + '
Error: ' + String(err.errorMsg).slice(0, 300) + '

ID ejecución: ' + err.executionId + (err.executionUrl ? '
' + err.executionUrl : '');
return [{ json: { twilioAuth, twilioUrl, adminTel, mensaje, twilioFrom: config.twilio_from } }];
